import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdir} from 'node:fs/promises';
import path from 'node:path';
import {fixture,open,search,detail} from './harness.mjs';

// The accepted reading colors are an external interface contract for the map,
// not values generated by the map stylesheet under test.
const palettes={
  light:{background:'rgb(248, 247, 243)',panel:'rgb(255, 255, 255)',text:'rgb(36, 36, 36)',control:'rgb(236, 235, 230)',hover:'rgb(224, 222, 215)',line:'rgb(133, 131, 124)'},
  dark:{background:'rgb(9, 9, 9)',panel:'rgb(21, 21, 21)',text:'rgb(244, 244, 244)',control:'rgb(37, 37, 37)',hover:'rgb(55, 55, 55)',line:'rgb(133, 133, 133)'}
};
const sourceId='ncei:453682';
async function localGeographyReady(page){
  // GeoJSON begins with Fiji, which Leaflet legitimately clips to M0 0 in a
  // US view. Require some painted geographic geometry in the map viewport.
  await page.waitForFunction(()=>{
    const map=document.getElementById('world-map'),viewport=map?.getBoundingClientRect();
    if(!viewport?.width||!viewport.height)return false;
    return [...map.querySelectorAll('path.context-land')].some(node=>{
      const geometry=node.getBBox(),box=node.getBoundingClientRect(),style=getComputedStyle(node);
      return geometry.width>0&&geometry.height>0&&box.width>0&&box.height>0&&
        box.right>viewport.left&&box.left<viewport.right&&box.bottom>viewport.top&&box.top<viewport.bottom&&
        style.display!=='none'&&style.visibility==='visible'&&Number(style.opacity)>0&&
        (style.fill!=='none'&&Number(style.fillOpacity)>0||style.stroke!=='none'&&Number(style.strokeOpacity)>0);
    });
  });
}
async function collectionState(page){return page.evaluate(()=>({
  controls:Object.fromEntries(['query','year','rating','state','quality','layer'].map(id=>[id,document.getElementById(id).value])),
  exhibits:document.getElementById('exhibits').checked,hasMedia:document.getElementById('has-media').checked,
  record:document.querySelector('#detail .eyebrow')?.textContent??null,
  source:document.querySelector('#detail .source-link')?.getAttribute('href')??null,
  selected:[...document.querySelectorAll('#results .result-button[aria-pressed="true"]')].map(node=>node.dataset.record),
  results:document.getElementById('results-count').textContent,mapCount:document.getElementById('map-count').textContent,
  panel:document.querySelector('.atlas-layout').dataset.mobileView,
  marker:document.querySelector('#world-map .map-selected')?.getAttribute('d')??null,
  href:location.href,share:document.getElementById('search-link').getAttribute('href'),history:history.length
}));}
function projectedView(view){
  const size=256*2**view[2],sine=Math.sin(view[0]*Math.PI/180);
  return {x:size*(view[1]+180)/360,y:size*(.5-Math.log((1+sine)/(1-sine))/(4*Math.PI))};
}
function serializationBound(view){
  const center=projectedView(view),half=.000005;
  return {x:Math.max(...[-half,half].map(delta=>Math.abs(projectedView([view[0],view[1]+delta,view[2]]).x-center.x))),
    y:Math.max(...[-half,half].map(delta=>Math.abs(projectedView([view[0]+delta,view[1],view[2]]).y-center.y)))};
}
function navigationState(actual,expected,history){
  // Navigation can retire Leaflet's cached center and expose its integer-pixel
  // origin. Appearance changes above still require byte-exact full state.
  const {href:aHref,share:aShare,marker:aMarker,history:aHistory,...a}=actual;
  const {href:bHref,share:bShare,marker:bMarker,history:bHistory,...b}=expected;
  assert.deepEqual(a,b,'Non-geographic collection state remains exact through navigation');
  assert.equal(aHistory,history,'Navigation does not add unintended history entries');
  const withoutView=(href,base)=>{const url=new URL(href,base);url.searchParams.delete('view');return url.href;};
  assert.equal(withoutView(aHref),withoutView(bHref),'Every non-view URL field remains exact');
  assert.equal(withoutView(aShare,aHref),withoutView(bShare,bHref),'Every non-view share-link field remains exact');
  const read=href=>{const parts=new URL(href).searchParams.get('view')?.split(',').map(Number);assert.ok(parts?.length===3&&parts.every(Number.isFinite));return parts;};
  const av=read(aHref),bv=read(bHref);assert.equal(av[2],bv[2],'The restored zoom remains exact');
  assert.equal(new URL(aShare,aHref).searchParams.get('view'),new URL(aHref).searchParams.get('view'),'Share link and address agree on the restored view');
  const ap=projectedView(av),bp=projectedView(bv),aq=serializationBound(av),bq=serializationBound(bv);
  const delta={x:ap.x-bp.x,y:ap.y-bp.y},limit={x:.5+aq.x+bq.x,y:.5+aq.y+bq.y};
  // Derive the bound from a half CSS pixel of Leaflet origin rounding plus
  // both five-decimal URL endpoint intervals, not a geographic epsilon.
  assert.ok(Math.abs(delta.x)<=limit.x,'Restored longitude exceeds the derived renderer bound');
  assert.ok(Math.abs(delta.y)<=limit.y,'Restored latitude exceeds the derived renderer bound');
  assert.ok(aMarker&&bMarker,'The selected marker remains part of the map');
  return {delta_css_pixels:delta,allowed_per_axis:limit,exact_href_equal:aHref===bHref};
}
async function selectedMarkerRendered(page){
  await page.waitForFunction(()=>{
    const node=document.querySelector('#world-map .map-selected'),map=document.getElementById('world-map');if(!node)return false;
    const box=node.getBoundingClientRect(),viewport=map.getBoundingClientRect();
    return box.width>0&&box.height>0&&box.right>viewport.left&&box.left<viewport.right&&box.bottom>viewport.top&&box.top<viewport.bottom;
  });
}
async function mapColors(page){return page.evaluate(()=>{
  const read=selector=>{const node=document.querySelector(selector);if(!node)return null;const css=getComputedStyle(node);return {
    background:css.backgroundColor,color:css.color,border:css.borderColor,outline:css.outlineColor,
    stroke:css.stroke,filter:css.filter,shadow:css.textShadow,decoration:css.textDecorationLine
  };};
  return {cluster:read('#world-map .catalogue-cluster'),pin:read('#world-map .catalogue-pin'),selected:read('#world-map .map-selected'),
    attribution:read('#world-map .leaflet-control-attribution'),link:read('#world-map .leaflet-control-attribution a'),scale:read('#world-map .leaflet-control-scale-line'),
    allScales:[...document.querySelectorAll('#world-map .leaflet-control-scale-line')].map(node=>({border:getComputedStyle(node).borderColor,shadow:getComputedStyle(node).textShadow}))};
});}
function checkColors(actual,scheme){
  const expected=palettes[scheme];
  if(actual.cluster){assert.equal(actual.cluster.background,expected.control);assert.equal(actual.cluster.color,expected.text);assert.equal(actual.cluster.border,expected.text);}
  if(actual.pin){assert.equal(actual.pin.background,expected.text);assert.equal(actual.pin.border,expected.background);}
  if(actual.selected){assert.equal(actual.selected.stroke,expected.text);assert.ok(actual.selected.filter.includes(expected.background),'Selection has the opposite reading-surface halo');}
  assert.equal(actual.attribution.background,expected.panel);assert.equal(actual.attribution.color,expected.text);
  assert.equal(actual.link.color,expected.text);assert.ok(actual.link.decoration.includes('underline'));
  assert.equal(actual.scale.background,expected.panel);assert.equal(actual.scale.color,expected.text);
  assert.equal(actual.scale.border,expected.line);assert.equal(actual.scale.shadow,'none');
  assert.ok(actual.allScales.length===2,'Metric and imperial scales remain present');
  for(const scale of actual.allScales){assert.equal(scale.border,expected.line);assert.equal(scale.shadow,'none');}
}
async function choose(page,value){await page.mouse.move(0,0);await page.locator('#reading-appearance').selectOption(value);assert.equal(await page.locator('#reading-appearance').inputValue(),value);}
async function readableControls(page){
  await page.locator('#world-map').scrollIntoViewIfNeeded();
  const scale=await page.locator('#world-map .leaflet-control-scale').boundingBox(),credit=await page.locator('#world-map .leaflet-control-attribution').boundingBox();
  assert.ok(scale&&credit&&scale.width>0&&credit.width>0);
  assert.ok(scale.x+scale.width<=credit.x||scale.y+scale.height<=credit.y,'Scale and wrapped attribution remain separate');
  assert.ok(await page.locator('#world-map .leaflet-control-scale-line').count());
  assert.match(await page.locator('#world-map .leaflet-control-scale').textContent(),/(km|m|mi|ft)/);
  assert.equal(await page.locator('#world-map .leaflet-control-attribution a[href="https://www.naturalearthdata.com/about/terms-of-use/"]').count(),1);
  assert.match(await page.locator('#world-map .leaflet-control-attribution').textContent(),/Natural Earth.*NOAA records/);
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),true);
}
async function capture(page,width,scheme,overview=false){
  const directory=process.env.ATLAS_MAP_APPEARANCE_CAPTURE;if(!directory)return;
  assert.ok(path.isAbsolute(directory),'An explicit owned capture directory is required');await mkdir(directory,{recursive:true});
  await page.locator('#world-map').scrollIntoViewIfNeeded();
  await page.screenshot({path:path.join(directory,(overview?'map-overview-':'map-')+width+'-'+scheme+'.png'),animations:'disabled'});
}

for(const width of [320,1280])test('Map reading palette and System appearance preserve collection state '+width,{timeout:60000},async t=>{
  const page=await fixture(t,{viewport:{width,height:900},reducedMotion:'reduce',serviceWorkers:'block'});
  await open(page);await page.locator('#world-map .catalogue-cluster').first().waitFor();await localGeographyReady(page);
  // Inspect a real group before narrowing to a selected single source.
  for(const scheme of ['light','dark']){
    await choose(page,scheme);const colors=await mapColors(page);assert.ok(colors.cluster);checkColors(colors,scheme);
    const cluster=page.locator('#world-map .catalogue-cluster').first();await cluster.hover();
    assert.equal(await cluster.evaluate(node=>getComputedStyle(node).backgroundColor),palettes[scheme].hover);
  }
  const overviewScheme=width===320?'dark':'light';await choose(page,overviewScheme);await readableControls(page);
  await capture(page,width,overviewScheme,true);
  await search(page,'El Reno');
  await page.locator('#advanced summary').click();await page.locator('#year').selectOption('2013');await page.locator('#advanced summary').click();
  const record=page.locator('#results [data-record="'+sourceId+'"]');await record.focus();await record.press('Enter');await detail(page,sourceId);
  if(width===320)await page.locator('#show-map').click();
  await page.locator('#center-selected').click();await page.locator('#world-map .map-selected').waitFor();
  await page.locator('#world-map .catalogue-pin[data-record="'+sourceId+'"]').waitFor();
  const baseline=await collectionState(page);assert.equal(baseline.record,sourceId);assert.equal(baseline.controls.query,'El Reno');assert.equal(baseline.controls.year,'2013');assert.equal(baseline.controls.layer,'local');
  const manual={};
  for(const scheme of ['light','dark']){
    await choose(page,scheme);manual[scheme]=await mapColors(page);checkColors(manual[scheme],scheme);
    assert.deepEqual(await collectionState(page),baseline);await readableControls(page);
    // Tab from Fit results reaches the adjacent zoom button without zooming.
    await page.locator('#fit').focus();await page.keyboard.press('Tab');
    const focus=await page.locator('#zoom-in').evaluate(node=>({active:document.activeElement===node,visible:node.matches(':focus-visible'),style:getComputedStyle(node).outlineStyle,width:getComputedStyle(node).outlineWidth,color:getComputedStyle(node).outlineColor}));
    assert.equal(focus.active,true);assert.equal(focus.visible,true);assert.equal(focus.style,'solid');assert.equal(focus.width,'3px');assert.equal(focus.color,palettes[scheme].text);
    await capture(page,width,scheme);
  }
  await choose(page,'system');assert.equal(await page.locator('html').getAttribute('data-appearance'),null);
  for(const scheme of ['light','dark']){
    await page.emulateMedia({colorScheme:scheme});
    await page.waitForFunction(expected=>getComputedStyle(document.querySelector('#world-map .leaflet-control-attribution')).backgroundColor===expected,palettes[scheme].panel);
    const system=await mapColors(page);checkColors(system,scheme);assert.deepEqual(system,manual[scheme],'System and explicit appearance resolve the same map styles');
    assert.deepEqual(await collectionState(page),baseline);await readableControls(page);
  }
  await page.reload();await page.waitForFunction(()=>document.body.dataset.ready==='true');await detail(page,sourceId);
  assert.equal(await page.locator('#reading-appearance').inputValue(),'system');assert.equal(await page.locator('html').getAttribute('data-appearance'),null);
  await selectedMarkerRendered(page);
  t.diagnostic('MAP_NAVIGATION_RELOAD '+JSON.stringify(navigationState(await collectionState(page),baseline,baseline.history)));
  await page.locator('#advanced summary').click();await page.locator('#year').selectOption('2011');await page.locator('#advanced summary').click();
  assert.equal(new URL(page.url()).searchParams.get('year'),'2011');
  const changedYear=await collectionState(page);assert.equal(changedYear.history,baseline.history+1,'The deliberate filter change adds one entry');
  await page.goBack();await page.waitForFunction(()=>document.getElementById('year').value==='2013');await detail(page,sourceId);
  await selectedMarkerRendered(page);const returned=await collectionState(page);
  t.diagnostic('MAP_NAVIGATION_BACK '+JSON.stringify(navigationState(returned,baseline,changedYear.history)));
  await page.goForward();await page.waitForFunction(()=>document.getElementById('year').value==='2011');await detail(page,sourceId);
  t.diagnostic('MAP_NAVIGATION_FORWARD '+JSON.stringify(navigationState(await collectionState(page),changedYear,changedYear.history)));
});

test('Map appearance retains selected source during optional provider failure and retry',{timeout:45000},async t=>{
  const page=await fixture(t,{viewport:{width:320,height:900},reducedMotion:'reduce',serviceWorkers:'block'});
  let failing=true,providerRequests=0;
  const image='<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256"><rect width="256" height="256" fill="#fafafa"/><path d="M0 128H256" stroke="#747474" stroke-width="4"/></svg>';
  // This fixture overrides the existing outside-origin block only for these
  // synthetic USGS responses. No request is forwarded to the provider.
  await page.route('https://basemap.nationalmap.gov/**',route=>{providerRequests++;return failing?route.fulfill({status:503,body:'Controlled provider failure'}):route.fulfill({contentType:'image/svg+xml',body:image});});
  await open(page,'&q=El%20Reno&year=2013&view=35.485,-98.096,10&panel=map#record=ncei%3A453682');await detail(page,sourceId);
  await localGeographyReady(page);
  await page.locator('.map-tools details summary').click();await page.locator('#layer').selectOption('topo');
  await page.waitForFunction(()=>document.getElementById('map-status').textContent.startsWith('USGS map unavailable.'));
  const failed=await collectionState(page);assert.equal(failed.record,sourceId);assert.equal(failed.controls.query,'El Reno');assert.equal(failed.controls.year,'2013');assert.ok(providerRequests>0);
  for(const scheme of ['light','dark']){
    await choose(page,scheme);checkColors(await mapColors(page),scheme);assert.deepEqual(await collectionState(page),failed);
    await localGeographyReady(page);assert.ok(await page.locator('#results [data-record]').count());
  }
  failing=false;await page.locator('#retry-map').click();
  await page.waitForFunction(()=>document.getElementById('map-status').textContent.startsWith('Modern USGS reference geography.'));
  assert.deepEqual(await collectionState(page),failed);
  assert.match(await page.locator('#world-map .leaflet-control-attribution').textContent(),/USGS The National Map and contributors/);
  assert.equal(await page.locator('#world-map .leaflet-control-attribution a[href="https://basemap.nationalmap.gov/arcgis/rest/services/USGSTopo/MapServer"]').count(),1);
  await readableControls(page);
});
